int dissect_unicode_string(tvbuff_t *tvb, int offset, packet_info *pinfo _U_, proto_tree *tree, guint8 *drep _U_, char **data, int hf_name) {
    /* Adjust offset to even boundary */
    if (offset % 2 != 0) {
        offset += 1;
    }

    /* Get the length of the remaining data at the adjusted offset */
    int length = tvb_reported_length_remaining(tvb, offset);
    if (length <= 0) {
        return offset;
    }

    /* Read the UTF-16 string from the tvb */
    char *utf16_str = tvb_get_unicode_string(wmem_packet_scope(), tvb, offset, length, ENC_UTF_16);

    /* Add the string to the protocol tree */
    if (tree) {
        proto_tree_add_string(tree, hf_name, tvb, offset, length, utf16_str);
    }

    /* Update the provided data pointer */
    if (data) {
        *data = utf16_str;
    }

    /* Return the new offset after reading the string */
    return offset + length;
}

int dissect_unicode_string(tvbuff_t *tvb, int offset, packet_info *pinfo, proto_tree *tree, guint8 *drep, char **data, int hf_name) {
    offset = (offset + 1) & ~1;

    int length = tvb_cstring_length(tvb, offset);
    if (length % 2 != 0) {
        length += 1;
    }

    *data = tvb_get_string_enc(wmem_packet_scope(), tvb, offset, length, ENC_UTF_16);
    proto_tree_add_string(tree, hf_name, tvb, offset, length, *data);
    return offset + length;
}

int dissect_unicode_string(tvbuff_t *tvb, int offset, packet_info *pinfo _U_, proto_tree *tree, guint8 *drep _U_, char **data, int hf_name) {
    offset = (offset + 1) & ~1; /* Adjust offset to even */
    tvbuff_t *sub_tvb = tvb_new_subset_remaining(tvb, offset);
    guint16 len = tvb_reported_length(sub_tvb);
    char *str = g_utf16_to_utf8(tvb_get_ptr(sub_tvb, 0, len), len, NULL, NULL, NULL);
    proto_tree_add_string(tree, hf_name, sub_tvb, 0, len * 2, str);
    *data = str;
    return offset + len * 2;
}

int dissect_unicode_string(tvbuff_t *tvb, int offset, packet_info *pinfo, proto_tree *tree, guint8 *drep, char **data, int hf_name) {
    int length = tvb_reported_length_remaining(tvb, offset);
    char *utf16_str;

    if (offset % 2 != 0) {
        offset++;
    }

    if (length % 2 != 0) {
        length--;
    }

    utf16_str = tvb_get_string_enc(wmem_packet_scope(), tvb, offset, length, ENC_UTF_16);

    if (tree) {
        proto_tree_add_string_format_value(tree, hf_name, tvb, offset, length, utf16_str, "%s", utf16_str);
    }

    if (data) {
        *data = utf16_str;
    }

    return offset + length;
}
